UPDATE CHB_EQUDET_SUB as A, ( select REGIST_BANK_CODE,INDENTIFY_MARK,REG_CODE,CHECK_SEQNO,BUSI_SEQNO from ( select TEMP.REGIST_BANK_CODE,TEMP.INDENTIFY_MARK, TEMP.REG_CODE, TEMP.CHECK_SEQNO,TEMP.BUSI_SEQNO from (
SELECT #{item.registBankCode} REGIST_BANK_CODE, #{item.indentifyMark} INDENTIFY_MARK, #{item.regCode,jdbcType=VARCHAR} REG_CODE, #{item.busiSeqno} BUSI_SEQNO, #{item.checkSeqno} CHECK_SEQNO FROM dual
) TEMP,CHB_EQUDET_SUB CII where CII.REGIST_BANK_CODE = TEMP.REGIST_BANK_CODE AND CII.INDENTIFY_MARK = TEMP.INDENTIFY_MARK AND CII.REG_CODE = TEMP.REG_CODE AND CII.BUSI_SEQNO = TEMP.BUSI_SEQNO AND CII.SUBMIT_STATUS = '01' ) de ) AS B set A.CHECK_SEQNO = B.CHECK_SEQNO where A.REGIST_BANK_CODE = B.REGIST_BANK_CODE AND A.INDENTIFY_MARK = B.INDENTIFY_MARK AND A.REG_CODE = B.REG_CODE AND A.BUSI_SEQNO = B.BUSI_SEQNO ;

